CREATE PROCEDURE CLAIMS.ADVANCED_CLAIM_EVALUATION (
    IN  P_CLAIM_ID          BIGINT,
    IN  P_TENANT_ID         CHAR(8),
    OUT P_DECISION          VARCHAR(30),
    OUT P_RISK_SCORE        DECIMAL(5,2)
)
LANGUAGE SQL
MODIFIES SQL DATA
P_ADVANCED_EVAL: BEGIN
    DECLARE V_CURRENT_TS          TIMESTAMP DEFAULT CURRENT TIMESTAMP;
    DECLARE V_CUSTOMER_ID         BIGINT;
    DECLARE V_CLAIM_AMOUNT        DECIMAL(15,2);
    DECLARE V_CLAIM_TYPE          VARCHAR(20);
    DECLARE V_CUSTOMER_TIER       VARCHAR(10);
    DECLARE V_LIFETIME_CLAIMS     INTEGER;
    DECLARE V_AVG_CLAIM_AMOUNT    DECIMAL(15,2);
    DECLARE V_MAX_SIMILAR_AMOUNT  DECIMAL(15,2);
    DECLARE V_RISK_WEIGHT         DECIMAL(5,2);
    DECLARE V_PEER_AVG_AMOUNT     DECIMAL(15,2);
    DECLARE V_SCORE               DECIMAL(10,2);

    SELECT C.CLAIM_AMOUNT,
           C.CLAIM_TYPE,
           C.CUSTOMER_ID,
           CU.CUSTOMER_TIER
    INTO V_CLAIM_AMOUNT,
         V_CLAIM_TYPE,
         V_CUSTOMER_ID,
         V_CUSTOMER_TIER
    FROM CLAIM AS C
    INNER JOIN CUSTOMER AS CU
        ON C.CUSTOMER_ID = CU.CUSTOMER_ID
       AND C.TENANT_ID = CU.TENANT_ID
    WHERE C.CLAIM_ID = P_CLAIM_ID
      AND C.TENANT_ID = P_TENANT_ID
      AND C.DELETED_IND = 'N';

    SELECT MAX(PREV.CLAIM_AMOUNT)
    INTO V_MAX_SIMILAR_AMOUNT
    FROM CLAIM CURR
    INNER JOIN CLAIM PREV
        ON CURR.CUSTOMER_ID = PREV.CUSTOMER_ID
       AND CURR.CLAIM_TYPE = PREV.CLAIM_TYPE
       AND CURR.CLAIM_ID <> PREV.CLAIM_ID
       AND CURR.TENANT_ID = PREV.TENANT_ID
    WHERE CURR.CLAIM_ID = P_CLAIM_ID
      AND CURR.TENANT_ID = P_TENANT_ID;

    SELECT COUNT(CL.CLAIM_ID), AVG(CL.CLAIM_AMOUNT)
    INTO V_LIFETIME_CLAIMS, V_AVG_CLAIM_AMOUNT
    FROM CLAIM CL
    INNER JOIN CUSTOMER_ACCOUNT ACC
        ON CL.CUSTOMER_ID = ACC.CUSTOMER_ID
       AND CL.TENANT_ID = ACC.TENANT_ID
    WHERE CL.CUSTOMER_ID = V_CUSTOMER_ID
      AND CL.TENANT_ID = P_TENANT_ID
      AND CL.STATUS IN ('APPROVED','PAID')
      AND CL.DELETED_IND = 'N';

    SELECT COALESCE(W.BASE_WEIGHT, 1.0) * COALESCE(C.MULTIPLIER, 1.0)
    INTO V_RISK_WEIGHT
    FROM RISK_FACTOR_WEIGHTS W
    CROSS JOIN SYSTEM_CONFIG C
    WHERE W.CLAIM_TYPE = V_CLAIM_TYPE
      AND W.CUSTOMER_TIER = V_CUSTOMER_TIER
      AND C.CONFIG_KEY = 'RISK_MULTIPLIER'
      AND C.ACTIVE_IND = 'Y'
    FETCH FIRST 1 ROW ONLY;

    SELECT AVG(PEER.CLAIM_AMOUNT)
    INTO V_PEER_AVG_AMOUNT
    FROM CLAIM PEER
    INNER JOIN CUSTOMER PCU
        ON PEER.CUSTOMER_ID = PCU.CUSTOMER_ID
       AND PEER.TENANT_ID = PCU.TENANT_ID
    WHERE PEER.CLAIM_TYPE = V_CLAIM_TYPE
      AND PCU.CUSTOMER_TIER = V_CUSTOMER_TIER
      AND PEER.STATUS IN ('APPROVED','PAID')
      AND PEER.DELETED_IND = 'N';

    SET V_SCORE = (
        (V_CLAIM_AMOUNT / NULLIF(V_PEER_AVG_AMOUNT, 0)) * 40.0 +
        (V_LIFETIME_CLAIMS * 0.5) +
        (CASE WHEN V_MAX_SIMILAR_AMOUNT > 0
              THEN V_CLAIM_AMOUNT / V_MAX_SIMILAR_AMOUNT * 30.0
              ELSE 0 END)
    ) * V_RISK_WEIGHT;

    SET P_RISK_SCORE = DECIMAL(ROUND(V_SCORE, 2), 5, 2);

    IF P_RISK_SCORE > 90.0 THEN
        SET P_DECISION = 'REJECTED_HIGH_RISK';
    ELSEIF P_RISK_SCORE > 75.0 THEN
        SET P_DECISION = 'MANUAL_REVIEW';
    ELSEIF V_LIFETIME_CLAIMS >= 10 AND V_AVG_CLAIM_AMOUNT > 5000 THEN
        SET P_DECISION = 'APPROVED_WITH_MONITORING';
    ELSE
        SET P_DECISION = 'APPROVED';
    END IF;
END P_ADVANCED_EVAL
